-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.notes (
  id text not null,
  slug text not null,
  course_id text not null,
  assessment_id text not null,
  kind text not null,
  title text not null,
  subtitle text,
  position integer default 0 not null,
  document jsonb not null,
  hash text not null,
  updated_at timestamp with time zone default now() not null,
  code text,
  version integer,
  version_hash text,
  published_at timestamp with time zone,
  version_at timestamp with time zone,
  constraint notes_pkey PRIMARY KEY (id),
  constraint notes_slug_key UNIQUE (slug),
  constraint notes_assessment_id_fkey FOREIGN KEY (assessment_id) REFERENCES public.assessments(id),
  constraint notes_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.courses(id),
  constraint notes_code_check CHECK ((code ~ '^QV-[A-Z0-9]+(-[A-Z0-9]+)+$'::text)),
  constraint notes_id_check CHECK ((id ~ '^AP-[A-Z0-9]+(-[A-Z0-9]+)+$'::text)),
  constraint notes_kind_check CHECK ((kind = ANY (ARRAY['lecture'::text, 'seminar'::text, 'practical'::text, 'summary'::text]))),
  constraint notes_version_check CHECK ((version >= 1))
);

CREATE INDEX notes_assessment ON public.notes USING btree (assessment_id, "position");
CREATE UNIQUE INDEX notes_code ON public.notes USING btree (code);

CREATE TRIGGER notes_restore_version BEFORE INSERT ON public.notes FOR EACH ROW EXECUTE FUNCTION public.restore_note_version();

alter table public.notes enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.notes to service_role;
